{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path, **kwargs):
    """Read a CSV of orders into a list of int-valued dicts."""
    with open(path, newline="") as fh:
        reader = csv.DictReader(fh)
        return [
            {"id": int(row["id"]), "qty": int(row["qty"]), "price": int(row["price"])}
            for row in reader
        ]
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    """Sum qty grouped by price."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": "def report(totals):
    """Text lines `price:total\\n` sorted by price."""
    return "".join(f"{price}:{totals[price]}\n" for price in sorted(totals))
"}
